// spec: specs/seo-robots-sitemap.md (3.1) · кейс: .qa/tests/seo-robots-sitemap/ROBOTS-04
// seed: tests/seed.spec.ts (гость) · прод: только GET через API request, без браузера.
import { test, expect } from '@playwright/test';
import { readRobots, robotsMeta, indexMeta } from './robots-sitemap.helpers';

// Каталог в Disallow → первая страница внутри него.
const DIR_PAGE: Record<string, string> = { '/qa/': '/qa/payments', '/payment/': '/payment/success' };

test.describe('Закрытые страницы — noindex вдобавок к Disallow', () => {
  test('Каждая страница из Disallow robots.txt отдаёт X-Robots-Tag noindex #d777c9 @desktop @prod-safe', async ({ request }) => {
    const { robots } = await readRobots(request);
    const star = robots.groups.filter((g) => g.agents.includes('*'));
    const disallowed = [...new Set(star.flatMap((g) => g.rules.filter((r) => !r.allow).map((r) => r.path)))];

    const pages: string[] = [];
    for (const p of disallowed) {
      if (p === '/api/') continue;
      if (p.endsWith('/')) {
        if (DIR_PAGE[p]) pages.push(DIR_PAGE[p]);
        else test.info().annotations.push({ type: 'skip-dir', description: `каталог ${p} без известной страницы` });
      } else if (!/[*$]/.test(p)) pages.push(p);
    }
    expect(pages.length, 'страниц из Disallow (20 минус /api/)').toBeGreaterThanOrEqual(19);

    const problems: string[] = [];
    for (const path of pages) {
      const res = await request.get(path);
      const header = res.headers()['x-robots-tag'] ?? '';
      const meta = robotsMeta(await res.text());
      if (res.status() !== 200) problems.push(`${path}: статус ${res.status()}`);
      if (!/noindex/i.test(header)) problems.push(`${path}: X-Robots-Tag «${header}» без noindex`);
      if (indexMeta(meta)) problems.push(`${path}: meta robots ${JSON.stringify(meta)}`);
    }
    expect(problems, 'закрытые страницы без noindex').toEqual([]);
  });
});
